#!/usr/bin/env python3
"""Offline non-specialist rendering from existing exports, no scientific rerun."""
import argparse,json
from pathlib import Path

def main():
    a=argparse.ArgumentParser(description=__doc__);a.add_argument('results',type=Path);a.add_argument('html',type=Path);p=a.parse_args()
    data=json.loads((p.results/'summary.json').read_text());m=json.loads((p.results/'manifest.json').read_text())
    if m['normative_names_enabled'] or m['normative_thresholds_enabled']:raise ValueError('P0 not passed: no normative rendering')
    def pick(unit,clock='MCU',width=60):return next(r for r in data if r['unit']==unit and r['clock']==clock and r['window_mcu_s']==width)
    v=pick('mm/s');acc=pick('mg');vv=pick('mm/s','QPC_ESTIMATE')
    rows=''.join(f"<tr><td>{r['unit']}</td><td>{r['clock']}</td><td>{r['window_mcu_s']} s MCU</td><td>{r['full_windows']}</td><td>{r['P50']:.3f}</td><td>{r['P95']:.3f}</td><td>{r['maximum']:.3f}</td><td>{r['population_std']:.3f}</td></tr>" for r in data)
    html=f'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PC machine — confort vibratoire exploratoire</title><style>body{{margin:0;background:#f4f7fa;color:#1d3246;font:16px/1.6 system-ui,sans-serif}}main{{max-width:1180px;padding:30px;margin:auto}}h1,h2{{line-height:1.2}}header{{border-bottom:3px solid #1a7d97}}.notice{{background:#fff1d7;border-left:5px solid #b77d12;padding:16px}}.cards{{display:flex;gap:16px;flex-wrap:wrap}}.card{{background:white;border-radius:8px;padding:18px;flex:1;min-width:210px}}.card strong{{display:block;font-size:30px}}section{{margin:30px 0}}img{{width:100%}}a{{color:#086e91}}table{{width:100%;border-collapse:collapse;font-size:14px}}td,th{{padding:8px;border-bottom:1px solid #cbd6df;text-align:left}}.scroll{{overflow:auto}}small{{color:#536d80}}@media print{{section{{break-inside:avoid}}body{{background:white}}}}</style><main>
<header><small>MSM TR2 · Campagne du31octobre2026 · E6N0005</small><h1>PC machine — confort vibratoire exploratoire</h1><p>Première lecture quantitative des vibrations locales. La méthode de confort pondérée reste à vérifier.</p></header>
<p class="notice"><b>Méthode normative indisponible : P0 bloquée.</b> Les valeurs ci-dessous sont NON PONDÉRÉES, calculées à sensibilité nominale sur XYZ capteur. Aucun Wm, équivalent ISO, seuil BV ou verdict «acceptable» n'est calculé. L'utilisateur ne dispose pas actuellement des clauses nécessaires.</p>
<section class="cards"><div class="card"><strong>{v['P50']:.2f} mm/s</strong>Médiane des maxima RMS directionnels · 60s MCU<br><small>Vitesse physique intégrée approximée, non pondérée</small></div><div class="card"><strong>{v['P95']:.2f} mm/s</strong>P95 des mêmes fenêtres<br><small>Pas un indice de confort ou d'exposition</small></div><div class="card"><strong>{acc['P50']:.2f} mg</strong>Médiane des maxima RMS directionnels · 60s<br><small>Accélération filtrée1–80Hz, distincte de l'ancienne bande2–25Hz</small></div></section>
<section><h2>Comment lire ces valeurs ?</h2><p>Chaque minute, on calcule le RMS de X, Y et Z puis on retient le plus élevé des trois. Le RMS décrit l'énergie moyenne du signal filtré ; une valeur plus élevée indique une vibration plus intense <b>selon cette méthode</b>, sans prouver une gêne humaine. Les axes du capteur ne sont pas repérés par rapport au navire.</p><p>Le point est au plancher du PC machine, avec fixation au double-face annoncée. L'occupation continue et la représentativité du point pour une personne ne sont pas vérifiées. La vitesse physique est obtenue par intégration numérique ; ce n'est pas nécessairement la grandeur équivalente utilisée dans un référentiel.</p></section>
<section><h2>Évolution réelle pendant l'enregistrement</h2><a href="unweighted_trends.png"><img src="unweighted_trends.png" alt="RMS accélération et vitesse intégrée non pondérées sur six heures, scénarios MCU et QPC"></a><p>Temps relatif MCU uniquement, UTC inconnue. Passe-bande Butterworth1–80Hz, gain−3,01dB aux bornes et retard causal. Les11sorties de warmup et10s de stabilisation sont exclues ; fenêtres incomplètes non utilisées pour les quantiles. Aucune lacune n'est remplie par zéro.</p></section>
<section><h2>Deux bases de temps, une réserve visible</h2><p>La cadence estimée MCU vaut{m['clocks']['MCU']:.3f}Hz, l'estimation tirée du témoinPC{m['clocks']['QPC_ESTIMATE']:.3f}Hz. Sur les mêmes minutes archivées, la médiane de vitesse devient{vv['P50']:.3f}mm/s dans le second scénario. Ce sont des hypothèses de calcul, pas deux campagnes et pas un étalonnage. L'incertitude totale ne se réduit pas à cet écart : amplitude, bruit, fixation et orientation restent non qualifiés.</p></section>
<section><h2>Résultats exportables</h2><p>Maximum directionnel XYZ capteur ; statistiques sur fenêtres FULL seulement. L'écart-type décrit la dispersion des fenêtres de cette campagne, pas une incertitude métrologique.</p><div class="scroll"><table><thead><tr><th>Unité</th><th>Scénario</th><th>Fenêtre</th><th>Nombre</th><th>P50</th><th>P95</th><th>Maximum</th><th>Écart-type</th></tr></thead><tbody>{rows}</tbody></table></div><p><a href="metrics.csv">Fenêtres60/120s, axes et qualité</a> · <a href="clock_sensitivity.csv">Sensibilité à l'horloge</a> · <a href="manifest.json">Provenance</a> · <a href="sqlite-proof.json">Persistance SQLite</a> · <a href="README.md">Méthode et limites</a></p></section>
<section><h2>Diagnostic technique conservé</h2><p>Les <a href="../TR2-20261031-R5-ANALYSE-PC-MACHINE-6H/index.html">RMS2–25Hz, spectrogrammes, PSD et raies de la première analyse</a> restent disponibles. Aucun résultat n'est remplacé. La comparaison d'équivalence entre campagnes est refusée tant que méthodes, horloges, échelles, pose et orientation ne sont pas compatibles et qualifiées.</p></section>
<section><h2>Ce qui manque pour parler de confort comparé</h2><p>Un accès autorisé à la définition Wm et aux clauses de méthode/équivalence ISO est indispensable, puis il faudra en vérifier numériquement l'implémentation et les unités. La réponse physique à1Hz, la cadence, le montage et les axes devront aussi être qualifiés. Aucun grade BV, seuil de santé, exposition A(8), causalité machine ou dommage structurel n'est déduit ici.</p><p>La source .TR2 a conservé ses octets et passe les contrôles internes. Le digest producteur indépendant en RAM reste perdu après la coupure : cette réserve historique n'est pas levée.</p></section><footer><small>Exploratoire non normatif · paquet local autonome · aucune intervention STM32 · revue indépendante ChatGPT suivante.</small></footer></main></html>'''
    with p.html.open('x',encoding='utf-8') as f:f.write(html)
if __name__=='__main__':main()
